const std = @import("std");

// Project Euler 96: solve the fifty supplied Sudoku grids and sum their prefixes.
const puzzles = "";

fn candidates(grid: *const [81]u8, position: usize) u16 {
    const row = position / 9;
    const column = position % 9;
    const box_row = row / 3 * 3;
    const box_column = column / 3 * 3;
    var used: u16 = 0;
    for (0..9) |i| {
        const row_value = grid[row * 9 + i];
        const column_value = grid[i * 9 + column];
        if (row_value != 0) used |= @as(u16, 1) << @intCast(row_value);
        if (column_value != 0) used |= @as(u16, 1) << @intCast(column_value);
    }
    for (box_row..box_row + 3) |r| for (box_column..box_column + 3) |c| {
        const value = grid[r * 9 + c];
        if (value != 0) used |= @as(u16, 1) << @intCast(value);
    };
    return (~used) & 0x3fe;
}

fn solve(grid: *[81]u8) bool {
    var position: ?usize = null;
    var choices: u16 = 0;
    var fewest: u5 = 10;
    for (0..81) |index| {
        if (grid[index] != 0) continue;
        const options = candidates(grid, index);
        const count: u5 = @popCount(options);
        if (count == 0) return false;
        if (count < fewest) {
            position = index;
            choices = options;
            fewest = count;
            if (count == 1) break;
        }
    }
    const index = position orelse return true;
    for (1..10) |digit| {
        if ((choices & (@as(u16, 1) << @intCast(digit))) == 0) continue;
        grid[index] = @intCast(digit);
        if (solve(grid)) return true;
    }
    grid[index] = 0;
    return false;
}

pub fn main() !void {
    var sum: usize = 0;
    for (0..50) |number| {
        var grid: [81]u8 = undefined;
        for (0..81) |index| grid[index] = puzzles[number * 81 + index] - '0';
        std.debug.assert(solve(&grid));
        sum += 100 * grid[0] + 10 * grid[1] + grid[2];
    }
    var buffer: [32]u8 = undefined;
    try std.Io.File.writeStreamingAll(std.Io.File.stdout(), std.Io.Threaded.global_single_threaded.io(), try std.fmt.bufPrint(&buffer, "{d}\n", .{sum}));
}
